import { normalizeAiCategory } from "@/lib/ai-civic-helpers";
import type { IssueCategory } from "@/types/civic";

export const AUDIT_DISCLAIMER_TEXT =
  "Independent estimate generated by CivicSnap Open Protocol. Not an official municipal tender quotation.";

export const BEFORE_AFTER_MIN_CONFIDENCE = 85;

export type CivicAuditCategory =
  | "Pothole / Road Damage"
  | "Open Manhole"
  | "Garbage Blackspot"
  | "Broken Footpath"
  | "Waterlogging";

export type CivicSlaPriority =
  | "P1 - Critical (<24h)"
  | "P2 - High (<48h)"
  | "P3 - Routine (<7d)";

export interface CivicEngineeringEstimates {
  estimated_dimensions: string;
  required_material: string;
  estimated_repair_cost_inr: number;
  labor_requirement: string;
}

export interface CivicSnapAuditProtocolOutput {
  is_civic_issue: boolean;
  rejection_reason: string | null;
  category: CivicAuditCategory | null;
  ticket_title: string | null;
  ticket_description: string | null;
  severity_score: number | null;
  sla_priority: CivicSlaPriority | null;
  engineering_estimates: CivicEngineeringEstimates | null;
  hazard_risk_summary: string | null;
  audit_disclaimer: string;
}

export interface CivicSnapBeforeAfterOutput {
  fix_verified: boolean;
  match_confidence_score: number;
  verdict: "Verified" | "Flagged";
  verificationStatus: "verified" | "flagged";
  aiConfidenceScore: number;
  reason: string;
  audit_disclaimer: string;
}

/**
 * Canonical System Instruction for CivicSnap AI — Independent Civic Engineering
 * and Ward Audit Engine for Bengaluru.
 */
export const CIVICSNAP_AI_SYSTEM_PROMPT = `You are "CivicSnap AI", an advanced, independent Civic Engineering and Ward Audit Engine.
You power an open-source, citizen-led civic accountability protocol for Bengaluru.

STRICT BUILDATHON COMPLIANCE & LEGAL MANDATE:
1. You are NOT a government body, BBMP employee, or municipal officer. Never impersonate state authorities or issue legal municipal penalties.
2. Frame all outputs as an "Independent Civic Audit & Ward Triage Protocol".
3. Maintain zero tolerance for fake reports, indoor photos, memes, selfies, and spam.

YOUR CORE TASKS:
Task 1: ANTI-SPAM & IMAGE VALIDITY CHECK
- Verify if the provided image shows a genuine outdoor civic/road hazard (pothole, broken footpath, open manhole, garbage dump, hanging wire, waterlogging, unlit streetlight).
- If the image is an indoor photo, selfie, meme, laptop screen, animal, food, or irrelevant screenshot, immediately mark "is_civic_issue": false, give a concise "rejection_reason", and set all metrics to null.

Task 2: HINGLISH TO FORMAL CIVIC TRANSLATION
- If the user input is Hinglish/Kannada-English slang (e.g., "Bhai HSR 27th main pe bohot bada khadda hai activa girte bachi"), translate and formalize it into a crisp municipal-grade engineering ticket in professional English.

Task 3: CIVIL ENGINEERING & COST ESTIMATION (Bengaluru Standard Rates)
- Estimate pothole/damage surface area (sq meters) and depth (cm).
- Estimate required repair material (e.g., Cold-Mix Asphalt in kg, wet mix macadam, or interlocking pavers).
- Estimate standard market repair cost in INR (₹).
- Assign a Severity Score (1 to 10) and SLA Priority Tier (P1 - Critical (<24h), P2 - High (<48h), P3 - Routine (<7d)).

Task 4: BEFORE-VS-AFTER VERIFICATION (When two images are provided)
- If an issue photo and a repair photo are provided, analyze if the specific defect has been filled/paved properly.
- Return "fix_verified" (boolean) and "match_confidence_score" (0-100).
- Only pass if confidence >= 85%.

OUTPUT FORMAT:
You MUST ALWAYS respond in pure, valid JSON with NO markdown formatting, NO conversational filler, and NO code fences.`;

export function normalizeProtocolCategory(raw: unknown): CivicAuditCategory {
  const value = typeof raw === "string" ? raw.trim().toLowerCase() : "";
  if (value.includes("manhole") || value.includes("drain") || value.includes("sewer")) {
    return "Open Manhole";
  }
  if (
    value.includes("garbage") ||
    value.includes("waste") ||
    value.includes("trash") ||
    value.includes("kachra") ||
    value.includes("dump") ||
    value.includes("blackspot")
  ) {
    return "Garbage Blackspot";
  }
  if (
    value.includes("footpath") ||
    value.includes("sidewalk") ||
    value.includes("paver") ||
    value.includes("pedestrian")
  ) {
    return "Broken Footpath";
  }
  if (
    value.includes("waterlog") ||
    value.includes("flood") ||
    value.includes("stagnant") ||
    value.includes("paani") ||
    value.includes("pani")
  ) {
    return "Waterlogging";
  }
  return "Pothole / Road Damage";
}

export function mapProtocolCategoryToIssueCategory(
  category: CivicAuditCategory | string | null | undefined
): IssueCategory {
  const raw = (category ?? "").trim().toLowerCase();
  if (raw.includes("garbage") || raw.includes("waste") || raw.includes("blackspot")) {
    return "waste";
  }
  if (raw.includes("pothole") || raw.includes("road") || raw.includes("footpath")) {
    return "pothole";
  }
  if (raw.includes("light") || raw.includes("lamp") || raw.includes("pole")) {
    return "streetlight";
  }
  if (raw.includes("manhole") || raw.includes("waterlog")) {
    return "other";
  }
  return normalizeAiCategory(category);
}

export function clampSeverityScore(raw: unknown): number {
  const n =
    typeof raw === "number"
      ? raw
      : typeof raw === "string"
        ? Number.parseFloat(raw)
        : Number.NaN;
  if (!Number.isFinite(n)) return 6;
  // If model returns a 100-scale value by mistake, normalize cleanly to 1-10
  const scaled = n > 10 ? Math.round(n / 10) : Math.round(n);
  return Math.min(10, Math.max(1, scaled));
}

export function normalizeSlaPriority(
  raw: unknown,
  severityScore: number
): CivicSlaPriority {
  const value = typeof raw === "string" ? raw.trim().toLowerCase() : "";
  if (value.includes("p1") || value.includes("critical") || value.includes("24h")) {
    return "P1 - Critical (<24h)";
  }
  if (value.includes("p2") || value.includes("high") || value.includes("48h")) {
    return "P2 - High (<48h)";
  }
  if (
    value.includes("p3") ||
    value.includes("routine") ||
    value.includes("moderate") ||
    value.includes("7d") ||
    value.includes("7 day")
  ) {
    return "P3 - Routine (<7d)";
  }
  if (severityScore >= 8) return "P1 - Critical (<24h)";
  if (severityScore >= 5) return "P2 - High (<48h)";
  return "P3 - Routine (<7d)";
}

export function extractAsphaltKgFromMaterial(
  requiredMaterial: string | null | undefined,
  fallbackKg = 0
): number {
  if (!requiredMaterial) return fallbackKg;
  const rangeMatch = requiredMaterial.match(/(\d+(?:\.\d+)?)\s*[-–to]+\s*(\d+(?:\.\d+)?)\s*kg/i);
  if (rangeMatch) {
    const low = Number.parseFloat(rangeMatch[1]);
    const high = Number.parseFloat(rangeMatch[2]);
    if (Number.isFinite(low) && Number.isFinite(high)) {
      return Math.min(5000, Math.max(0, Math.round((low + high) / 2)));
    }
  }
  const singleMatch = requiredMaterial.match(/(\d+(?:\.\d+)?)\s*kg/i);
  if (singleMatch) {
    const kg = Number.parseFloat(singleMatch[1]);
    if (Number.isFinite(kg)) {
      return Math.min(5000, Math.max(0, Math.round(kg)));
    }
  }
  return fallbackKg;
}

export function severityScoreToLegacyLabel(
  severityScore: number
): "Critical" | "High" | "Medium" | "Low" {
  if (severityScore >= 8) return "Critical";
  if (severityScore >= 6) return "High";
  if (severityScore >= 4) return "Medium";
  return "Low";
}

export function normalizeCivicAuditResponse(
  raw: Record<string, unknown>,
  locality = "Bengaluru"
): CivicSnapAuditProtocolOutput {
  const isCivicIssue = raw.is_civic_issue === true;

  if (!isCivicIssue) {
    const rawReason =
      typeof raw.rejection_reason === "string"
        ? raw.rejection_reason.replace(/\s+/g, " ").trim().slice(0, 320)
        : "";
    return {
      is_civic_issue: false,
      rejection_reason:
        rawReason ||
        "Image rejected by Independent Civic Audit Protocol: photo does not show a genuine outdoor Bengaluru civic or road hazard.",
      category: null,
      ticket_title: null,
      ticket_description: null,
      severity_score: null,
      sla_priority: null,
      engineering_estimates: null,
      hazard_risk_summary: null,
      audit_disclaimer: AUDIT_DISCLAIMER_TEXT,
    };
  }

  const category = normalizeProtocolCategory(raw.category);
  const severityScore = clampSeverityScore(raw.severity_score);
  const slaPriority = normalizeSlaPriority(raw.sla_priority, severityScore);

  const ticketTitle =
    (typeof raw.ticket_title === "string"
      ? raw.ticket_title.replace(/\s+/g, " ").trim().slice(0, 120)
      : "") || `${category} Hazard Reported in ${locality}`;

  const ticketDescription =
    (typeof raw.ticket_description === "string"
      ? raw.ticket_description.replace(/\s+/g, " ").trim().slice(0, 600)
      : "") ||
    `Outdoor ${category.toLowerCase()} defect documented in ${locality}, Bengaluru requiring field inspection and civil remediation.`;

  const rawEst =
    raw.engineering_estimates && typeof raw.engineering_estimates === "object"
      ? (raw.engineering_estimates as Record<string, unknown>)
      : {};

  const rawCost = Number(rawEst.estimated_repair_cost_inr);
  const estimatedRepairCostInr =
    Number.isFinite(rawCost) && rawCost > 0
      ? Math.min(500000, Math.round(rawCost))
      : category === "Pothole / Road Damage"
        ? 3800
        : 2500;

  const estimatedDimensions =
    (typeof rawEst.estimated_dimensions === "string"
      ? rawEst.estimated_dimensions.replace(/\s+/g, " ").trim().slice(0, 160)
      : "") || "Approx 1.2m x 0.8m surface affected";

  const requiredMaterial =
    (typeof rawEst.required_material === "string"
      ? rawEst.required_material.replace(/\s+/g, " ").trim().slice(0, 220)
      : "") ||
    (category === "Pothole / Road Damage"
      ? "Approx 120 kg Cold-Mix Bituminous Asphalt"
      : "Standard civic field remediation supplies");

  const laborRequirement =
    (typeof rawEst.labor_requirement === "string"
      ? rawEst.labor_requirement.replace(/\s+/g, " ").trim().slice(0, 160)
      : "") || "2 field technicians with standard tools (approx 45-60 mins)";

  const hazardRiskSummary =
    (typeof raw.hazard_risk_summary === "string"
      ? raw.hazard_risk_summary.replace(/\s+/g, " ").trim().slice(0, 240)
      : "") ||
    "Elevated commuter and pedestrian safety risk, especially during monsoon or low-visibility hours.";

  return {
    is_civic_issue: true,
    rejection_reason: null,
    category,
    ticket_title: ticketTitle,
    ticket_description: ticketDescription,
    severity_score: severityScore,
    sla_priority: slaPriority,
    engineering_estimates: {
      estimated_dimensions: estimatedDimensions,
      required_material: requiredMaterial,
      estimated_repair_cost_inr: estimatedRepairCostInr,
      labor_requirement: laborRequirement,
    },
    hazard_risk_summary: hazardRiskSummary,
    audit_disclaimer: AUDIT_DISCLAIMER_TEXT,
  };
}

/**
 * Enforces CivicSnap AI Task 4 Before-vs-After Verification rule:
 * Only passes when fix_verified is true AND match_confidence_score >= 85%.
 */
export function normalizeBeforeAfterVerification(raw: {
  fix_verified?: unknown;
  match_confidence_score?: unknown;
  verdict?: unknown;
  aiConfidenceScore?: unknown;
  reason?: unknown;
}): CivicSnapBeforeAfterOutput {
  const rawScore = Number(
    raw.match_confidence_score ?? raw.aiConfidenceScore ?? Number.NaN
  );
  const rawVerified =
    raw.fix_verified === true ||
    (typeof raw.verdict === "string" &&
      raw.verdict.trim().toLowerCase() === "verified");

  const matchConfidenceScore = Number.isFinite(rawScore)
    ? Math.min(100, Math.max(0, Math.round(rawScore)))
    : rawVerified
      ? 88
      : 40;

  const passed =
    rawVerified && matchConfidenceScore >= BEFORE_AFTER_MIN_CONFIDENCE;

  const cleanReason =
    typeof raw.reason === "string"
      ? raw.reason.replace(/\s+/g, " ").trim().slice(0, 400)
      : "";

  const reason =
    cleanReason.length >= 3
      ? cleanReason
      : passed
        ? `Independent Civic Audit confirmed the reported defect is properly repaired (${matchConfidenceScore}% match confidence).`
        : `Repair could not be verified at the required ${BEFORE_AFTER_MIN_CONFIDENCE}% confidence threshold (scored ${matchConfidenceScore}%).`;

  return {
    fix_verified: passed,
    match_confidence_score: matchConfidenceScore,
    verdict: passed ? "Verified" : "Flagged",
    verificationStatus: passed ? "verified" : "flagged",
    aiConfidenceScore: matchConfidenceScore,
    reason,
    audit_disclaimer: AUDIT_DISCLAIMER_TEXT,
  };
}
